/**
 * Stripe Node - Version 1
 * Discriminator: resource=customer, operation=get
 */


interface Credentials {
  stripeApi: CredentialReference;
}

/** Get a balance */
export type StripeV1CustomerGetParams = {
  resource: 'customer';
  operation: 'get';
/**
 * ID of the customer to retrieve
 */
    customerId: string | Expression<string>;
};

export type StripeV1CustomerGetOutput = {
  address?: {
    country?: string;
  };
  balance?: number;
  created?: number;
  delinquent?: boolean;
  discount?: null;
  id?: string;
  invoice_prefix?: string;
  invoice_settings?: {
    custom_fields?: null;
    footer?: null;
    rendering_options?: null;
  };
  livemode?: boolean;
  next_invoice_sequence?: number;
  object?: string;
  preferred_locales?: Array<string>;
  tax_exempt?: string;
  test_clock?: null;
};

export type StripeV1CustomerGetNode = {
  type: 'n8n-nodes-base.stripe';
  version: 1;
  config: NodeConfig<StripeV1CustomerGetParams> & { credentials?: Credentials };
  output?: Items<StripeV1CustomerGetOutput>;
};